:'redeem','🔐':'lock','→':'arrow_forward','←':'arrow_back','✓':'check_circle','×':'close','✕':'close','📥':'download','📤':'upload','📋':'content_copy','🗑️':'delete','✏️':'edit','⚙️':'settings','🔍':'search','❤️':'favorite','⭐':'star','ℹ️':'info','❓':'help','⚠️':'warning','✅':'check_circle','❌':'cancel','🔗':'link','🌐':'language','📄':'description','📁':'folder','🖼️':'image','🎨':'palette','🔄':'sync','▶️':'play_arrow','⏸️':'pause','⏹️':'stop','⏱️':'timer','📊':'analytics','👥':'group','👤':'person','🏠':'home','🧰':'construction','🔑':'key','💾':'save','📌':'push_pin'};const esc=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const keys=Object.keys(map).sort((a,b)=>b.length-a.length);const re=new RegExp(keys.map(esc).join('|'),'g');const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode:n=>{if(!n.nodeValue||!re.test(n.nodeValue))return NodeFilter.FILTER_REJECT;const p=n.parentElement;if(!p||p.closest('script,style,textarea,input,.material-symbols-outlined,.material-symbols-rounded,.material-symbols-sharp'))return NodeFilter.FILTER_REJECT;re.lastIndex=0;return NodeFilter.FILTER_ACCEPT}});const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(n=>{const frag=document.createDocumentFragment();let last=0;const text=n.nodeValue;re.lastIndex=0;let m;while((m=re.exec(text))){if(m.index>last)frag.appendChild(document.createTextNode(text.slice(last,m.index)));const s=document.createElement('span');s.className='material-symbols-outlined';s.textContent=map[m[0]];s.setAttribute('aria-hidden','true');frag.appendChild(s);last=m.index+m[0].length}if(last<text.length)frag.appendChild(document.createTextNode(text.slice(last)));n.parentNode.replaceChild(frag,n)});})();</script>
<script>(()=>{const loggedIn=<?=!empty($_SESSION['user_id'])?'true':'false'?>;const path=location.pathname;if(loggedIn||!/\/smart-toolz\/tools\/[^/]+\.php$/i.test(path))return;const slug=path.split('/').pop().replace(/\.php$/i,'');const nav=document.querySelector('.nav-links');if(nav){const login=nav.querySelector('.login-btn');const pill=document.createElement('span');pill.className='guest-trial-pill';pill.id='guestTrialPill';pill.innerHTML='<span class="material-symbols-outlined" aria-hidden="true">redeem</span> 5 / 5 free trials';if(login)nav.insertBefore(pill,login);else nav.appendChild(pill)}const pill=document.getElementById('guestTrialPill');const note=document.querySelector('.trial-note');function set(v){if(pill){pill.innerHTML='<span class="material-symbols-outlined" aria-hidden="true">redeem</span> '+v+' / 5 free trials';pill.classList.toggle('empty',Number(v)<=0)}if(note)note.innerHTML='<span class="material-symbols-outlined" aria-hidden="true">redeem</span> <b>'+v+' of 5 free trials</b> left for this tool.'}async function status(){try{const r=await fetch('/smart-toolz/api/trial.php?action=status&tool='+encodeURIComponent(slug),{cache:'no-store'});const d=await r.json();if(d.ok&&d.guest)set(d.remaining)}catch(e){}}async function consume(){try{const r=await fetch('/smart-toolz/api/trial.php?action=consume&tool='+encodeURIComponent(slug),{method:'POST',cache:'no-store'});const d=await r.json();if(d.ok&&d.guest){set(d.remaining);return true}if(d.reason==='trial_exhausted'){set(0);alert('Your 5 free trials for this tool are finished. Please login to continue using credits.');return false}return false}catch(e){alert('Unable to start the free trial right now.');return false}}let busy=false;document.addEventListener('submit',async e=>{const f=e.target;if(!(f instanceof HTMLFormElement)||!f.closest('main')||f.dataset.guestApproved==='1')return;e.preventDefault();if(busy)return;busy=true;if(await consume()){f.dataset.guestApproved='1';f.requestSubmit();f.dataset.guestApproved=''}busy=false},{capture:true});document.addEventListener('click',async e=>{const el=e.target.closest('main button,main input[type="submit"]');if(!el||el.closest('form')||el.dataset.guestApproved==='1'||el.disabled)return;e.preventDefault();if(busy)return;busy=true;if(await consume()){el.dataset.guestApproved='1';el.click();el.dataset.guestApproved=''}busy=false},{capture:true});status()})();</script>
